2921	      itd->hw.trans[uf] = sunxi_swap32(flags);
2922	    }
2923	
2924	  /* Set the next-link pointer for the chain. */
2925	
2926	  itd->hw.nlp = nlp;
2927	
2928	  up_clean_dcache((uintptr_t)&itd->hw,
2929	                  (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
2930	  UP_DSB();
2931	}
