/* (1) If we have buffered payloads, serve as many as fit into
 * the caller buffer in one shot.  Each payload is framed as
 * [u16 LE length][payload bytes]; the UVC layer splits them
 * back apart (each payload still begins with its own 12-byte
 * UVC header).  Batching amortizes the per-DRVR_TRANSFER
 * lock/unlock/callstack overhead (~167us) across many payloads
 * so the consumer keeps up with the controller's ~8000
 * payload/s fill rate — otherwise the controller laps the ring
 * and overwrites unread iTDs, tearing the frame.
 */

if (g_ring.f_cnt > 0)
  {
    size_t   used    = 0;
    uint32_t served  = 0;

    while (g_ring.f_cnt > 0)
      {
        uint32_t len = g_ring.fifo_len[g_ring.f_head];
        uint8_t *src = g_ring.fifo +
                       (size_t)g_ring.f_head * ISOC_FIFO_SLOTSZ;

        /* Stop once the next framed payload won't fit, but
         * always take at least one so we never stall.
         */

        if (served > 0 &&
            used + 2 + len > g_ring.user_buflen)
          {
            break;
          }

        /* Defensive: a lone payload larger than the whole
         * buffer is truncated (never happens for 800-byte
         * payloads in a 32K buffer).
         */

        if ((size_t)(2 + len) > g_ring.user_buflen)
          {
            len = (uint32_t)(g_ring.user_buflen - 2);
          }

        g_ring.user_buf[used]     = (uint8_t)(len & 0xff);
        g_ring.user_buf[used + 1] = (uint8_t)((len >> 8) & 0xff);
        memcpy(g_ring.user_buf + used + 2, src, len);
        used   += (size_t)(2 + len);
        served += 1;

        g_ring.f_head = (g_ring.f_head + 1) % ISOC_FIFO_SLOTS;
        g_ring.f_cnt--;
      }

    epinfo->xfrd    = used;
    epinfo->result  = OK;
    epinfo->iocwait = false;
    return epinfo->result;
  }

