  static uint32_t d_hdr_ok;   /* byte0==12 && EOH set */
  static uint32_t d_full;     /* rem == 788 */
  static uint32_t d_800;      /* rem == 800 (hdr+data) */
  static uint32_t d_short;    /* 0<rem<788 */
  static uint32_t d_other;    /* rem>800 */
  FAR const uint8_t *pp =
    itd->buffer + (uint32_t)uf * per_uf;
  uint8_t hlen = pp[0];
  uint8_t info = pp[1];

  d_tot++;
  if ((hlen == 12 || hlen == 2) && (info & 0x80))
    {
      d_hdr_ok++;
    }

  if (rem == 788)      d_full++;
  else if (rem == 800) d_800++;
  else if (rem < 788)  d_short++;
  else                 d_other++;

  if ((d_tot % 2000) == 0)
    {
      syslog(LOG_ERR,
        "HDRPROBE: tot=%u hdrOK=%u full788=%u p800=%u "
        "short=%u other=%u\n",
        d_tot, d_hdr_ok, d_full, d_800, d_short,
        d_other);
    }
}

