/* DIAG (lag probe, read-only): how many iTDs is the controller
 * ahead of the consumer?  FRINDEX bits 3-13 are the current
 * frame number; the controller writes iTD (frame % POOL) this
 * 1ms.  lag = (ctrl_itd - ring_head) mod POOL.  If lag often
 * approaches/exceeds POOL, the controller laps the ring and
 * overwrites unread iTDs (→ B/deeper ring is the fix).  If lag
 * stays small, the ring is NOT the bottleneck (→ layer-2).
 */

{
  static uint32_t lp_n;
  static uint32_t lp_sum;
  static uint32_t lp_max;
  static uint32_t lp_ge_half;   /* lag >= POOL/2 */
  static uint32_t lp_ge_pool;   /* lag >= POOL-1 (near lap) */
  uint32_t fri  = sunxi_getreg(&HCOR->frindex) &
                  EHCI_FRINDEX_MASK;
  uint32_t frm  = fri >> 3;              /* frame number */
  uint32_t citd = frm % ISOC_ITD_POOL;  /* iTD ctrl writes now */
  uint32_t lag  = (citd + ISOC_ITD_POOL - g_ring.ring_head) %
                  ISOC_ITD_POOL;

  lp_n++;
  lp_sum += lag;
  if (lag > lp_max) lp_max = lag;
  if (lag >= (ISOC_ITD_POOL / 2))  lp_ge_half++;
  if (lag >= (ISOC_ITD_POOL - 1))  lp_ge_pool++;

  if ((lp_n % 2000) == 0)
    {
      syslog(LOG_ERR,
        "LAGPROBE: n=%u avg=%u max=%u ge_half=%u ge_pool=%u "
        "(POOL=%u)\n",
        lp_n, lp_sum / lp_n, lp_max, lp_ge_half, lp_ge_pool,
        (unsigned)ISOC_ITD_POOL);
    }
}

