/* Buffer Page Pointer List.  Each iTD owns only ISOC_ITD_BUFSZ (8K = 2
 * pages) of DMA buffer, so ONLY bpl[0] and bpl[1] may point into it.
 * With 8 payloads * per_uf (<=800) = <=6400 bytes, every transaction's
 * data lands within the first 2 pages, so the hardware only ever
 * dereferences bpl[0]/bpl[1].  bpl[2..6] must still hold LEGAL addresses
 * (the controller may prefetch them); pointing them past this iTD's 2-page
 * buffer walks into the next iTD's buffer — or, for the last iTD, past the
 * whole g_ring.buf allocation → Data abort.  Point them all at pgbase
 * (page 0, always valid, never actually used for data).
 */

{
  uintptr_t pgbase = bufphys & ITD_BUFPTR_MASK;

  itd->hw.bpl[0] = sunxi_swap32(
    ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
    ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
    (pgbase & ITD_BUFPTR_MASK));

  itd->hw.bpl[1] = sunxi_swap32(
    ((uint32_t)maxpkt << ITD_BUFPTR1_MAXPKT_SHIFT) |
    (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
    ((pgbase + 0x1000) & ITD_BUFPTR_MASK));

  {
    uint32_t multi_val = (epinfo->mult == 3) ? ITD_BUFPTR2_MULTI_3 :
                         (epinfo->mult == 2) ? ITD_BUFPTR2_MULTI_2 :
                                               ITD_BUFPTR2_MULTI_1;

    /* bpl[2] carries the Multi field; its page pointer is unused for
     * mult==1 with a 2-page buffer, so keep it at pgbase (valid).
     */

    itd->hw.bpl[2] = sunxi_swap32(multi_val |
                                  (pgbase & ITD_BUFPTR_MASK));
  }

  /* bpl[3..6]: unused for our 2-page buffer.  Keep them at the (valid)
   * page-aligned base so the controller never dereferences an address
   * outside this iTD's buffer.
   */

  itd->hw.bpl[3] = sunxi_swap32(pgbase & ITD_BUFPTR_MASK);
  itd->hw.bpl[4] = sunxi_swap32(pgbase & ITD_BUFPTR_MASK);
  itd->hw.bpl[5] = sunxi_swap32(pgbase & ITD_BUFPTR_MASK);
  itd->hw.bpl[6] = sunxi_swap32(pgbase & ITD_BUFPTR_MASK);
}

