/* Buffer Page Pointer List.  Each iTD owns only ISOC_ITD_BUFSZ (8K = 2
 * pages), so ONLY bpl[0]/bpl[1] may point into it.  With 8 payloads *
 * per_uf(<=800) = <=6400 bytes, every transaction lands within the first 2
 * pages, so the controller only ever dereferences bpl[0]/bpl[1].  bpl[2..6]
 * must still be LEGAL (the controller may prefetch); pointing them past
 * this iTD's 2-page buffer walks into the next iTD's buffer — or, for the
 * last iTD, past the whole g_ring.buf allocation.  Keep them all at pgbase
 * (page 0, always valid, never used for data).
 */

{
  uintptr_t pgbase = bufphys & ITD_BUFPTR_MASK;

  itd->hw.bpl[0] = sunxi_swap32(
    ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
    ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
    (pgbase & ITD_BUFPTR_MASK));

  itd->hw.bpl[1] = sunxi_swap32(
    ((uint32_t)maxpkt << ITD_BUFPTR1_MAXPKT_SHIFT) |
    (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
    ((pgbase + 0x1000) & ITD_BUFPTR_MASK));

  {
    uint32_t multi_val = (epinfo->mult == 3) ? ITD_BUFPTR2_MULTI_3 :
                         (epinfo->mult == 2) ? ITD_BUFPTR2_MULTI_2 :
                                               ITD_BUFPTR2_MULTI_1;

    /* bpl[2] carries the Multi field; its page pointer is unused for a
     * 2-page buffer, so keep it at pgbase (valid).
     */

    itd->hw.bpl[2] = sunxi_swap32(multi_val |
                                  (pgbase & ITD_BUFPTR_MASK));
