/****************************************************************************
 * Name: sunxi_isoc_harvest
 *
 * Description:
 *   Scan the iTD ring from ring_head forward; for each COMPLETED iTD (no
 *   transaction still ACTIVE), copy its payloads into the software FIFO,
 *   immediately re-arm the iTD so the controller keeps filling it, and
 *   advance ring_head.  Stop at the first still-ACTIVE iTD to preserve
 *   chronological order.
 *
 *   This is the PRODUCER half of the ISOC pipeline.  It is called from the
 *   IOC interrupt bottom-half (sunxi_ioc_bottomhalf, ~1ms cadence) so that
 *   harvesting runs continuously and decoupled from the consumer
 *   (sunxi_ioc_wait's serve path).  Previously harvest ran inline in the
 *   consumer, which stalled it whenever the stream thread was busy
 *   processing a batch — letting the controller lap the ring and tear
 *   frames.  A fallback call also exists in the serve path in case an
 *   interrupt is missed.
 *
 *   Concurrency: FIFO tail (f_tail/f_cnt) and ring_head are shared with the
 *   consumer running on another CPU (SMP).  memcpy and dcache ops run
 *   outside the lock; only the shared-index updates are wrapped in a
 *   critical section (global spinlock + IRQ off).
 *
 *   Returns the number of payloads harvested this call.
 *
 ****************************************************************************/

static int sunxi_isoc_harvest(void)
{
  uint32_t per_uf;
  int harvested = 0;
  int scan;

  if (g_ring.epinfo == NULL || g_ring.buf == NULL)
    {
      return 0;
    }

  per_uf = (uint32_t)g_ring.maxpacket *
           (g_ring.epinfo->mult ? g_ring.epinfo->mult : 1);

  for (scan = 0; scan < ISOC_ITD_POOL; scan++)
    {
      int idx = (g_ring.ring_head + scan) % ISOC_ITD_POOL;
      struct sunxi_itd_s *itd = &g_itdpool[idx];
      bool active = false;
      int uf;

      up_invalidate_dcache((uintptr_t)&itd->hw,
        (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));

      for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
        {
          if (sunxi_swap32(itd->hw.trans[uf]) & ITD_TRAN_STATUS_ACTIVE)
            {
              active = true;
              break;
            }
        }

      if (active)
        {
          break;  /* Chronological boundary; stop harvest */
        }

      /* iTD completed: harvest its payloads into the FIFO. */

      up_invalidate_dcache((uintptr_t)itd->buffer,
        (uintptr_t)itd->buffer + (size_t)ISOC_ITD_UFRAMES * per_uf);

      for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
        {
          uint32_t   tran = sunxi_swap32(itd->hw.trans[uf]);
          uint32_t   rem  = (tran & ITD_TRAN_LENGTH_MASK) >>
                            ITD_TRAN_LENGTH_SHIFT;
          bool       err  = (tran & (ITD_TRAN_STATUS_XACTERR |
                                     ITD_TRAN_STATUS_BABBLE |
                                     ITD_TRAN_STATUS_DBERROR)) != 0;
          irqstate_t flags;
          uint16_t   tail;
          uint32_t   n;

          if (err || rem == 0)
            {
              continue;
            }

          /* DIAG: cumulative harvest counter, logged every 2000 payloads. */

          {
            static uint32_t h_pls;
            static uint32_t h_bytes;

            h_pls++;
            h_bytes += rem;
            if ((h_pls % 2000) == 0)
              {
                syslog(LOG_ERR, "HARVEST: pls=%u bytes=%u\n", h_pls, h_bytes);
              }
          }

          /* Reserve a FIFO slot under the lock (shared with consumer). */

          n = rem > ISOC_FIFO_SLOTSZ ? ISOC_FIFO_SLOTSZ : rem;

          flags = enter_critical_section();
          if (g_ring.f_cnt >= ISOC_FIFO_SLOTS)
            {
              leave_critical_section(flags);

              {
                static uint32_t diag_full;
                if ((diag_full++ % 200) == 0)
                  {
                    syslog(LOG_ERR, "HARVEST fifo full #%u\n", diag_full);
                  }
              }

              continue;
            }

          tail = g_ring.f_tail;
          g_ring.f_tail = (tail + 1) % ISOC_FIFO_SLOTS;
          g_ring.f_cnt++;
          leave_critical_section(flags);

          /* Copy the payload into the reserved slot outside the lock.  The
           * slot is exclusively ours until the consumer reaches it (it only
           * reads slots behind f_tail up to f_cnt), so this is safe.
           */

          memcpy(g_ring.fifo + (size_t)tail * ISOC_FIFO_SLOTSZ,
                 itd->buffer + (uint32_t)uf * per_uf, n);
          g_ring.fifo_len[tail] = (uint16_t)n;

          harvested++;
        }

      /* Re-arm immediately so the controller keeps filling this iTD. */

      {
        FAR uint8_t *buffer = g_ring.buf + (size_t)idx * ISOC_ITD_BUFSZ;
        sunxi_itd_arm(idx, buffer, g_ring.nlp);
      }

      /* Advance ring_head under the lock (shared with LAGPROBE/consumer). */

      {
        irqstate_t flags = enter_critical_section();
        g_ring.ring_head = (g_ring.ring_head + 1) % ISOC_ITD_POOL;
        leave_critical_section(flags);
      }
    }

  return harvested;
}

