/****************************************************************************
 * Name: sunxi_isoc_harvest_thread
 *
 * Description:
 *   Independent harvest thread for the ISOC pipeline.  Runs continuously
 *   for the lifetime of the stream: waits on hvsem (posted by the IOC ISR
 *   on every iTD completion, ~1ms cadence), calls sunxi_isoc_harvest() to
 *   copy completed iTD payloads into the FIFO, and posts consem to wake
 *   the consumer.
 *
 *   This decouples harvest from the consumer's DRVR_TRANSFER cycle,
 *   breaking the "1ms IOC wait per transfer" bottleneck that limited
 *   throughput to ~3200 payload/s.  With a separate harvest thread the
 *   FIFO stays continuously topped up; the consumer just drains it
 *   without waiting for IOC.
 *
 ****************************************************************************/

static int sunxi_isoc_harvest_thread(int argc, FAR char *argv[])
{
  (void)argc;
  (void)argv;

  while (g_ring.streaming)
    {
      /* Wait for the IOC ISR to signal that data may be ready. */

      nxsem_wait_uninterruptible(&g_ring.hvsem);

      if (!g_ring.streaming)
        {
          break;
        }

      /* Harvest all completed iTDs into the FIFO. */

      sunxi_isoc_harvest();

      /* If the FIFO now has payloads, wake the consumer. */

      if (g_ring.f_cnt > 0)
        {
          nxsem_post(&g_ring.consem);
        }
    }

  return OK;
}

